206	/// The type for a panic-handling closure. Note that this same closure
207	/// may be invoked multiple times in parallel.
208	type PanicHandler = dyn Fn(Box<dyn Any + Send>) + Send + Sync;
209	
210	/// The type for a closure that gets invoked when a thread starts. The
211	/// closure is passed the index of the thread on which it is invoked.
212	/// Note that this same closure may be invoked multiple times in parallel.
213	type StartHandler = dyn Fn(usize) + Send + Sync;
214	
215	/// The type for a closure that gets invoked when a thread exits. The
216	/// closure is passed the index of the thread on which it is invoked.
217	/// Note that this same closure may be invoked multiple times in parallel.
218	type ExitHandler = dyn Fn(usize) + Send + Sync;
